    static int checks,flatGroups;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static Exchange exchange(Snapshot x,List<Snapshot> cuts,Packet p,Map<Cut,PrivatePool> pools){return ContextUniversalGroupedCompletionRunner.exchange(x,cuts,p,pools);}
