    static Result close(Result base,List<ContextUniversalGroupedCompletion.Receipt> seeds,int depth){return ContextUniversalFrozenConstraints.closeSignedGrouped(base,seeds,16,depth,512,256,WORK);}
    static void yes(Result r){require(r.closed,r.reason);ContextUniversalFrozenConstraints.check(r,16,ContextGroundProductionRounds.budget(WORK));}
    static void no(Result r,String why){require(!r.closed&&r.proofs.isEmpty()&&r.emptyProofs.isEmpty()&&!r.xRefuted&&!r.foreignRefuted,why+": "+r.reason);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean refused=false;try{a.run();}catch(IllegalStateException|IllegalArgumentException|UnsupportedOperationException expected){refused=true;}require(refused,why);}
    static void audit(Proof p,Set<Proof> seen){if(!seen.add(p))return;require(p.grouped==null&&p.exchanged==null&&p.compound==null,"no owning receipt/Result/Packet import in rejection DAG");
        if(p.original!=null){require(p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source))&&p.clause.equivalent(ContextUniversalInputResiduals.schema(p.part.clause,()->{}),()->{}),"actual original typed root and whole Source retained");return;}
        if(p.input!=null){require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof)&&p.clause.equivalent(ContextUniversalInputResiduals.fact(p.input,()->{}),()->{}),"actual input Item/Support binding retained");return;}
        Set<Source> sources=new LinkedHashSet<>();int grade=0;Residual expected;
        if(!p.groupedConclusions.isEmpty()){++flatGroups;audit(p.producer,seen);sources.addAll(p.producer.support.sources);grade=p.producer.support.depth;Map<Integer,Residual> clauses=new LinkedHashMap<>();for(Map.Entry<Integer,Proof> e:p.groupedDonors.entrySet()){audit(e.getValue(),seen);clauses.put(e.getKey(),e.getValue().clause);sources.addAll(e.getValue().support.sources);grade=Math.max(grade,e.getValue().support.depth);}org.kanger.ContextUniversalInputResiduals.GroupedApplication binding=ContextUniversalInputResiduals.applyGroupedUnits(p.producer.clause,new LinkedHashSet<>(p.groupedConclusions),clauses,()->{});require(binding!=null&&binding.instances.keySet().equals(p.groupedInstances.keySet()),"flattened original grouped recipe complete");for(int slot:binding.instances.keySet())require(ContextUniversalInputResiduals.sameOrdered(binding.instances.get(slot),p.groupedInstances.get(slot),()->{}),"all actual grouped donor instances retained");expected=binding.conclusion;
        }else if(p.producer!=null){audit(p.producer,seen);sources.addAll(p.producer.support.sources);grade=p.producer.support.depth;List<Residual> clauses=new ArrayList<>();for(Proof donor:p.donors){audit(donor,seen);clauses.add(donor.clause);sources.addAll(donor.support.sources);grade=Math.max(grade,donor.support.depth);}if(p.instantiatedUnitRecipe||p.groundedMixedRecipe){org.kanger.ContextUniversalInputResiduals.GroundedApplication b=p.instantiatedUnitRecipe?ContextUniversalInputResiduals.applyInstantiatedUnits(p.producer.clause,p.conclusion,clauses,()->{}):ContextUniversalInputResiduals.applyGroundedMixedUnits(p.producer.clause,p.conclusion,clauses,()->{});require(b!=null,"actual old instantiated recipe retained");expected=b.conclusion;}else expected=p.symbolicHeadRecipe?ContextUniversalInputResiduals.applySymbolicHeadFixedUnits(p.producer.clause,p.conclusion,clauses,()->{}):p.conclusion<0?ContextUniversalInputResiduals.applyFixedPositiveUnits(p.producer.clause,clauses,()->{}):ContextUniversalInputResiduals.applyFixedSignedUnits(p.producer.clause,p.conclusion,clauses,()->{});
        }else{audit(p.unit,seen);audit(p.horn,seen);sources.addAll(p.unit.support.sources);sources.addAll(p.horn.support.sources);grade=Math.max(p.unit.support.depth,p.horn.support.depth);expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});}
        require(ContextUniversalInputResiduals.sameOrdered(expected,p.clause,()->{})&&p.support.depth==grade+1&&p.support.sources.equals(sources),"independent flattened inference/Source/max-parent+1 replay");
    }
    static void mainCase(boolean contracted,String head)throws Exception {
        Snapshot x=bind(true,contracted?"!pair(1,1);":"!anchor(1); !@u p(u);"),a=bind(false,contracted?"!@x @y (pair(x,y)&&b(x)&&b(y)&&c(x)->r(y)) && hidden(99);":"!@x (p(x)&&b(x)->r(x)) && hidden(99);"),b=bind(false,contracted?"!b(1); !c(1); !~r(1);":"!b(1); !~r(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.emptyMap());ResidualProof c=e.clauses.stream().filter(q->q.clause.literals.size()==(contracted?3:2)).findFirst().get();Result old=base(x,b,p,e);ContextUniversalGroupedCompletion.Receipt seed=receipt(e,c,old,head);List<ContextUniversalGroupedCompletion.Receipt> mutable=new ArrayList<>(Collections.singletonList(seed));Result r=close(old,mutable,2);yes(r);require(r.reason.contains("explicit grouped seed manifest")&&r.reason.contains("automatic grouped enumeration"),"result states explicit-manifest scope, not automatic grouped completeness");ContextUniversalFrozenConstraints.check(r,2,ContextGroundProductionRounds.budget(WORK));require(r.xRefuted&&!r.foreignRefuted&&r.emptyProofs.stream().anyMatch(q->q.support.depth==2&&q.support.sources.size()==(contracted?5:4)),"actual kernel empty2 with complete physical Sources");require(old.emptyProofs.stream().noneMatch(q->q.support.depth<3),"old receiver keeps original empty3");require(r.groupedBase==old&&r.groupedInputs.size()==1&&r.groupedInputs.get(0)==seed,"actual explicit manifest and base identity retained");Proof node=r.proofs.stream().filter(q->q.grouped==seed).findFirst().get();require(node.clause==seed.clause&&node.support==seed.support&&node.producer==seed.history.producer&&node.groupedDonors.equals(seed.donors)&&node.groupedConclusions.size()==(head.equals("b")?2:1),"kernel node actual original parents/instances/full conclusion group");require(r.proofs.stream().noneMatch(q->q.clause!=null&&q.clause.literals.size()==1&&q.clause.literals.get(0).predicate.equals("hidden")),"unrelated physical row member not imported");
        int before=flatGroups;List<Proof> flat=ContextUniversalFrozenConstraints.rejectionEvidence(r,WORK);require(!flat.isEmpty(),"rejection evidence emitted after actual check");for(Proof q:flat){require(q.support.depth==2,"short empty grade remains2 after flattening");audit(q,Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>()));}require(flatGroups>before,"flattened rejection retains grouped original application recipe");reject(()->ContextUniversalFrozenConstraints.rejectionEvidence(r,1),"bounded rejection has no partial return");mutable.clear();require(r.groupedInputs.size()==1,"caller manifest copied");reject(()->r.groupedInputs.clear(),"manifest immutable");
        no(close(old,Collections.singletonList(seed),1),"empty2 obligation cannot be hidden at bound1");no(ContextUniversalFrozenConstraints.closeSignedGrouped(old,Collections.singletonList(seed),1,16,512,256,WORK),"round refusal no prefix");no(ContextUniversalFrozenConstraints.closeSignedGrouped(old,Collections.singletonList(seed),16,16,1,256,WORK),"capacity refusal no prefix");no(ContextUniversalFrozenConstraints.closeSignedGrouped(old,Collections.singletonList(seed),16,16,512,256,1),"work refusal no prefix");no(close(old,Collections.nCopies(513,seed),16),"explicit manifest cap512 no prefix");
        Result alternate=base(x,b,p,e);no(close(alternate,Collections.singletonList(seed),16),"same values but different actual base cannot consume receipt");ContextUniversalGroupedCompletion.Receipt other=receipt(e,c,alternate,head);no(close(old,Arrays.asList(seed,other),16),"late different actual base suppresses valid seed prefix");Result empty=close(old,Collections.emptyList(),16);yes(empty);require(empty.emptyProofs.stream().noneMatch(q->q.support.depth<3),"empty manifest never claims automatic grouped candidate enumeration");
        java.lang.reflect.Field inputs=Result.class.getDeclaredField("groupedInputs");inputs.setAccessible(true);List<ContextUniversalGroupedCompletion.Receipt> saved=r.groupedInputs;inputs.set(r,Collections.emptyList());reject(()->ContextUniversalFrozenConstraints.check(r,16,()->{}),"checker refuses omitted actual grouped seed manifest");inputs.set(r,saved);
        java.lang.reflect.Field proofs=Result.class.getDeclaredField("proofs");proofs.setAccessible(true);List<Proof> all=r.proofs;List<Proof> omitted=new ArrayList<>();for(Proof q:all)if(!(q.clause!=null&&q.clause.equivalent(seed.clause,()->{})&&q.support.sources.equals(seed.support.sources)&&q.support.depth<=seed.support.depth))omitted.add(q);proofs.set(r,omitted);boolean covered=false;try{ContextUniversalFrozenConstraints.check(r,16,()->{});}catch(IllegalStateException expected){covered=expected.getMessage().contains("Uncovered explicit grouped seed");}require(covered,"independent checker refuses missing explicit seed cover even when child DAG still references it");proofs.set(r,all);
        java.lang.reflect.Field support=Proof.class.getDeclaredField("support");support.setAccessible(true);Support actual=node.support;support.set(node,new Support(actual.sources,0));reject(()->ContextUniversalFrozenConstraints.check(r,16,()->{}),"checker refuses kernel grade reset");support.set(node,actual);
        java.lang.reflect.Field grouped=Proof.class.getDeclaredField("grouped");grouped.setAccessible(true);grouped.set(node,null);reject(()->ContextUniversalFrozenConstraints.check(r,16,()->{}),"frame-free rejection node cannot substitute as live kernel receipt");grouped.set(node,seed);
    }
    static void exactSourceMinima()throws Exception {
        Snapshot x=bind(true,"!p(1) && (@u p(u)->q(u));"),a=bind(false,"!@x (p(x)&&c(x)->r(x)) && (q(x)&&b(x)->r(x));"),b=bind(false,"!b(1) && (@u b(u)->d(u)) && (@v d(v)->c(v));");Packet p=ContextPrivateWitnessPoolRunner.common(x);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.emptyMap());Result base=base(x,b,p,e);require(e.clauses.stream().allMatch(q->q.support.depth<=2),"all actual carried compound alternatives fit bound2");List<ContextUniversalGroupedCompletion.Receipt> candidates=new ArrayList<>();for(ResidualProof c:e.clauses)if(c.clause.literals.size()==2&&c.clause.literals.stream().anyMatch(l->l.predicate.equals("b")||l.predicate.equals("c"))&&c.clause.literals.stream().anyMatch(l->l.predicate.equals("r"))){ContextUniversalCompoundOccurrences.Receipt h=ContextUniversalGroupedCompletionRunner.history(e,c,base);for(Proof donor:base.proofs)if(donor.clause!=null&&donor.clause.literals.size()==1&&donor.clause.literals.get(0).predicate.equals(c.clause.literals.stream().filter(l->!l.predicate.equals("r")).findFirst().get().predicate)&&donor.clause.literals.get(0).positive)candidates.add(ContextUniversalGroupedCompletionRunner.yes(ContextUniversalGroupedCompletion.complete(h,ContextUniversalGroupedCompletionRunner.position(c.clause,"r"),Collections.singletonMap(ContextUniversalGroupedCompletionRunner.position(c.clause,donor.clause.literals.get(0).predicate),donor),16,WORK)));}
        ContextUniversalGroupedCompletion.Receipt shorter=null,deeper=null;for(ContextUniversalGroupedCompletion.Receipt first:candidates)for(ContextUniversalGroupedCompletion.Receipt second:candidates)if(first.support.depth==2&&second.support.depth==3&&first.support.sources.equals(second.support.sources)&&first.clause.equivalent(second.clause,()->{})){shorter=first;deeper=second;}require(shorter!=null&&deeper!=null,"genuine original application2 and3 share exactly the same physical Source set");
        for(boolean reverse:Arrays.asList(false,true)){List<ContextUniversalGroupedCompletion.Receipt> seeds=reverse?Arrays.asList(shorter,deeper):Arrays.asList(deeper,shorter);Result r=close(base,seeds,2);yes(r);ContextUniversalFrozenConstraints.check(r,2,ContextGroundProductionRounds.budget(WORK));ContextUniversalGroupedCompletion.Receipt actual=shorter;require(r.proofs.stream().anyMatch(q->q.grouped==actual&&q.support.depth==2)&&r.proofs.stream().noneMatch(q->q.support.depth>2),"combine actual exact-Source minima before bound2, both manifest orders");require(r.groupedInputs.size()==2,"authentic over-bound nonminimal recipe remains in manifest, covered by actual shorter proof");}
    }
    static void privateAndDerived()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@x @y pair(x,y)&&b(x)&&b(y)&&c(x)->r(y);"),a=bind(false,"!$u pair(u,u);"),b=bind(false,"!@u b(u); !@u c(u); !@u ~r(u);");Packet p=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,a,WORK);Exchange e=exchange(x,Arrays.asList(a,b),p,Collections.singletonMap(pool.cut,pool));ResidualProof c=e.clauses.stream().filter(q->!q.clause.origins.isEmpty()).findFirst().get();Result old=base(x,b,p,e);ContextUniversalGroupedCompletion.Receipt seed=receipt(e,c,old,"r");Result r=close(old,Collections.singletonList(seed),16);yes(r);require(r.xRefuted&&r.emptyProofs.stream().anyMatch(q->q.support.depth==2),"actual private-Origin grouped kernel empty2");require(e.clauses.stream().anyMatch(q->q.support.depth>2),"private fixture also carries deeper exact Source alternatives");no(close(old,Collections.singletonList(seed),2),"short empty2 does not excuse deeper carried compound alternatives at bound2");for(Proof q:ContextUniversalFrozenConstraints.rejectionEvidence(r,WORK))audit(q,Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>()));
        Snapshot dx=bind(true,"!pair(1,1);"),da=bind(false,"!@x @y pair(x,y)&&b(x)&&b(y)&&c(x)->r(y);"),db=bind(false,"!seed(1); !@u seed(u)->b(u); !c(1);");Packet dp=ContextPrivateWitnessPoolRunner.common(dx);Exchange de=exchange(dx,Arrays.asList(da,db),dp,Collections.emptyMap());ResidualProof dc=de.clauses.stream().filter(q->q.clause.literals.size()==3).findFirst().get();Result base=base(dx,db,dp,de);ContextUniversalGroupedCompletion.Receipt derived=receipt(de,dc,base,"r");require(derived.support.depth==2,"actual receiver parent1 yields seed2");Result dr=close(base,Collections.singletonList(derived),2);yes(dr);require(dr.proofs.stream().anyMatch(q->q.grouped==derived&&q.support.depth==2&&q.support.sources.size()==5),"derived donor kernel grade2/all Sources retained");no(close(base,Collections.singletonList(derived),1),"over-bound explicit seed cannot silently disappear");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("grouped-kernel-").toString());mainCase(false,"r");mainCase(true,"r");mainCase(true,"b");exactSourceMinima();privateAndDerived();System.out.println("CONTEXT_UNIVERSAL_GROUPED_KERNEL_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
